export const HOA11_CHUONG6_HANDBOOK = [{"title":"1. Hợp Chất Carbonyl (Aldehyde & Ketone)","icon":"⚡","content":["Hợp chất carbonyl là các hợp chất hữu cơ chứa nhóm carbonyl >C=O. Nếu nhóm carbonyl liên kết với ít nhất một nguyên tử H thì là aldehyde (R–CHO); nếu liên kết với 2 gốc hydrocarbon thì là ketone (R–CO–R').","<b>Danh pháp IUPAC:</b> Tên hydrocarbon tương ứng + đuôi 'al' (cho aldehyde); hoặc + đuôi 'on' kèm số chỉ vị trí nhóm C=O (cho ketone).","<b>Phản ứng khử:</b> Aldehyde bị khử bởi NaBH<sub>4</sub> hoặc LiAlH<sub>4</sub> tạo alcohol bậc 1; Ketone tạo alcohol bậc 2."]},{"title":"2. Phản Ứng Oxi Hóa & Phản Ứng Tráng Bạc","icon":"✨","content":["<b>Phản ứng với thuốc thử Tollens (AgNO<sub>3</sub>/NH<sub>3</sub>):</b> Aldehyde bị oxi hóa tạo lớp bạc sáng bóng bám vào thành ống nghiệm (phản ứng tráng bạc): RCHO + 2[Ag(NH<sub>3</sub>)<sub>2</sub>]OH → RCOONH<sub>4</sub> + 2Ag↓ + 3NH<sub>3</sub> + H<sub>2</sub>O. (Riêng HCHO tạo tỉ lệ 1 mol : 4 mol Ag). Ketone không có phản ứng này.","<b>Phản ứng với Cu(OH)<sub>2</sub> trong kiềm đun nóng:</b> Aldehyde tạo kết tủa đỏ gạch Cu<sub>2</sub>O: RCHO + 2Cu(OH)<sub>2</sub> + NaOH → RCOONa + Cu<sub>2</sub>O↓ + 3H<sub>2</sub>O.","<b>Phản ứng Iodoform:</b> Các hợp chất chứa nhóm CH<sub>3</sub>–C=O (hoặc CH<sub>3</sub>–CH(OH)–) phản ứng với I<sub>2</sub> trong môi trường kiềm tạo kết tủa vàng nhạt CHI<sub>3</sub> (triiodomethane)."]},{"title":"3. Carboxylic Acid (Cấu Tạo, Tính Acid & Phản Ứng Ester Hóa)","icon":"🧪","content":["Carboxylic acid là những hợp chất hữu cơ trong phân tử chứa nhóm carboxyl (–COOH) liên kết với gốc hydrocarbon hoặc nguyên tử H.","<b>Nhiệt độ sôi cao nhất</b> trong các hợp chất hữu cơ cùng phân tử khối do tạo được <b>liên kết hydrogen dạng dimer</b> phân cực rất mạnh.","<b>Tính acid:</b> Là các acid yếu nhưng có đầy đủ tính chất của một acid (làm quỳ tím chuyển màu đỏ; tác dụng kim loại đứng trước H giải phóng H<sub>2</sub>; tác dụng bazơ và oxit bazơ tạo muối + nước; đẩy được acid yếu hơn như H<sub>2</sub>CO<sub>3</sub> ra khỏi muối carbonate giải phóng CO<sub>2</sub>).","<b>Phản ứng ester hóa:</b> RCOOH + R'OH ⇌ RCOOR' + H<sub>2</sub>O (xúc tác H<sub>2</sub>SO<sub>4</sub> đặc, đun nóng, phản ứng thuận nghịch 2 chiều)."]}];

