const STORAGE_PREFIX = 'hoa11_c6_';

export interface Chuong6ExamAttempt {
  id: string;
  examId: string;
  examTitle: string;
  score: number;
  part1Score: number;
  part2Score: number;
  part3Score: number;
  correctCount: number;
  totalQuestions: number;
  durationSeconds: number;
  tabSwitchCount: number;
  autoSubmittedDueToViolation?: boolean;
  date: string;
  formattedDate: string;
  answers: Record<string | number, any>;
}

export interface Chuong6UserProgress {
  completedLessons: string[];
  examScores: Record<string, { score: number; date: string; attempts: number }>;
  practiceScores: Record<string, number>;
  totalXP: number;
  streakDays: number;
  lastActiveDate: string;
  rankTitle: string;
}

export function getChuong6UserProgress(): Chuong6UserProgress {
  try {
    const raw = localStorage.getItem(`${STORAGE_PREFIX}progress`);
    if (raw) return JSON.parse(raw);
  } catch (e) {}
  return {
    completedLessons: [],
    examScores: {},
    practiceScores: {},
    totalXP: 100,
    streakDays: 1,
    lastActiveDate: new Date().toISOString(),
    rankTitle: 'Tập Sự Hóa Học'
  };
}

export function calculateChuong6ExamScore(questionsInput: any, userAnswers: Record<string | number, any>) {
  const questions: Chuong6Question[] = Array.isArray(questionsInput) ? questionsInput : (questionsInput?.questions || []);
  let rawScore = 0;
  let part1Score = 0;
  let part2Score = 0;
  let part3Score = 0;
  let correctCount = 0;
  const breakdown: Record<number, any> = { 1: { correct: 0, total: 0 }, 2: { correct: 0, total: 0 }, 3: { correct: 0, total: 0 } };

  questions.forEach((q, idx) => {
    const part = q.part || 1;
    if (!breakdown[part]) breakdown[part] = { correct: 0, total: 0 };
    breakdown[part].total++;

    const ans = userAnswers[q.id] ?? userAnswers[q.number] ?? userAnswers[q.displayNumber ?? (idx + 1)];
    if (part === 1) {
      const correctOpt = q.options?.find(o => o.isCorrect)?.letter || q.correctAnswer;
      if (ans && correctOpt && String(ans).trim().toUpperCase() === String(correctOpt).trim().toUpperCase()) {
        rawScore += 0.25;
        part1Score += 0.25;
        correctCount++;
        breakdown[1].correct++;
      }
    } else if (part === 2) {
      if (typeof ans === 'object' && ans !== null) {
        let subCorrect = 0;
        q.options?.forEach(opt => {
          const userVal = ans[opt.letter] ?? ans[opt.letter.toLowerCase()];
          const expVal = opt.isCorrect !== undefined ? opt.isCorrect : (String(opt.text).includes('Đúng') || String(opt.text).includes('đúng'));
          if (userVal !== undefined && Boolean(userVal) === Boolean(expVal)) {
            subCorrect++;
          }
        });
        let added = 0;
        if (subCorrect === 1) added = 0.1;
        else if (subCorrect === 2) added = 0.25;
        else if (subCorrect === 3) added = 0.5;
        else if (subCorrect === 4) { added = 1.0; correctCount++; }
        rawScore += added;
        part2Score += added;
        if (subCorrect === 4) breakdown[2].correct++;
      }
    } else if (part === 3) {
      const expected = String(q.correctAnswer || '').trim().toLowerCase().replace(',', '.');
      const userText = String(ans || '').trim().toLowerCase().replace(',', '.');
      if (userText && (userText === expected || expected.includes(userText))) {
        rawScore += 0.5;
        part3Score += 0.5;
        correctCount++;
        breakdown[3].correct++;
      }
    }
  });

  const finalScore = Math.min(10, Math.round(rawScore * 10) / 10);
  return {
    score: finalScore,
    part1Score: Math.round(part1Score * 100) / 100,
    part2Score: Math.round(part2Score * 100) / 100,
    part3Score: Math.round(part3Score * 100) / 100,
    correctCount,
    totalQuestions: questions.length,
    breakdown
  };
}

export function getChuong6ExamHistory(examId?: string): Chuong6ExamAttempt[] {
  try {
    const raw = localStorage.getItem(`${STORAGE_PREFIX}history`);
    if (raw) {
      const list: Chuong6ExamAttempt[] = JSON.parse(raw);
      if (examId) return list.filter(a => a.examId === examId);
      return list;
    }
  } catch (e) {}
  return [];
}

export function saveChuong6ExamAttempt(attempt: Chuong6ExamAttempt) {
  try {
    const list = getChuong6ExamHistory();
    list.unshift(attempt);
    localStorage.setItem(`${STORAGE_PREFIX}history`, JSON.stringify(list.slice(0, 30)));

    const prog = getChuong6UserProgress();
    prog.totalXP += Math.round(attempt.score * 15);
    localStorage.setItem(`${STORAGE_PREFIX}progress`, JSON.stringify(prog));
  } catch (e) {}
}

export function saveChuong6ExamResult(examId: string, score: number, durationSeconds: number = 0) {
  try {
    const prog = getChuong6UserProgress();
    prog.examScores[examId] = {
      score,
      date: new Date().toISOString(),
      attempts: (prog.examScores[examId]?.attempts || 0) + 1
    };
    localStorage.setItem(`${STORAGE_PREFIX}progress`, JSON.stringify(prog));
  } catch (e) {}
}

export function shuffleChuong6Exam(exam: Chuong6Exam): Chuong6Exam {
  const qList = [...exam.questions];
  const p1 = qList.filter(q => q.part === 1);
  const p2 = qList.filter(q => q.part === 2);
  const p3 = qList.filter(q => q.part === 3);

  const shuffleArray = (arr: any[]) => {
    const res = [...arr];
    for (let i = res.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [res[i], res[j]] = [res[j], res[i]];
    }
    return res;
  };

  const shuffledP1 = shuffleArray(p1).map(q => {
    if (!q.options) return q;
    return { ...q, options: shuffleArray(q.options) };
  });

  const combined = [...shuffledP1, ...p2, ...p3];
  combined.forEach((q, idx) => {
    q.displayNumber = idx + 1;
  });

  return {
    ...exam,
    questions: combined
  };
}

export function getRankTitle(xp: number): string {
  if (xp >= 3000) return 'Huyền Thoại Thủ Khoa';
  if (xp >= 2000) return 'Kiện Tướng Hóa Học';
  if (xp >= 1200) return 'Bậc Thầy Lý Thuyết';
  if (xp >= 600) return 'Chiến Binh 9+';
  if (xp >= 300) return 'Học Sinh Chăm Chỉ';
  return 'Tập Sự Hóa Học';
}

export const getChuong6RankTitle = getRankTitle;
